sub('ch06','ch06_forward_choke_java',r'study\.addChoke\("Source-B", "Down-B", "Choke-B", 15\.0, 80\.0\);', 'study.addChoke("Source-B", "Down-B", "Choke-B", 15.0, 80.0);\nstudy.getPipe("Choke-A").setChokeUseValveModel(true);\nstudy.getPipe("Choke-B").setChokeUseValveModel(true);\nstudy.setRelaxationFactor(1.0);','Activated supported forward gas capacity at critical flow instead of capped loss screening.')
sub('ch06','ch06_compact_iterations',r'study\.setMaxIterations\(100\);','study.setMaxIterations(200);','Allowed sufficient nonlinear iterations without changing100Pa acceptance tolerance.')
